package agent

import (
	"errors"
	"strings"
	"text/template"
	"text/template/parse"
	"time"
	"unicode/utf8"

	"github.com/EdouardRichard/EzTest/backend/internal/platform"
)

// MaxPromptRunes is the frozen profile prompt length limit (spec §8.4).
const MaxPromptRunes = 32768

// Prompt revision sources of the frozen contract.
const (
	PromptSourceSeed  = "seed"
	PromptSourceAdmin = "admin"
	PromptSourceReset = "reset"
)

// PromptVariableSourceRuntime is the only allowed variable source: values are
// generated by the server at run time (spec §8.4).
const PromptVariableSourceRuntime = "runtime"

// ErrPromptVersionConflict reports an expected_version mismatch. The
// application maps it to 409 state_conflict.
var ErrPromptVersionConflict = errors.New("agent: prompt version conflict")

// PromptVariable is one controllable prompt template variable. The catalog is
// code-defined; values are never supplied by a client at run time.
type PromptVariable struct {
	Name        string `json:"name"`
	Description string `json:"description"`
	Example     string `json:"example"`
	Source      string `json:"source"`
}

// PromptRevision is one append-only agent_profile_prompt_revision row.
type PromptRevision struct {
	ID           int64
	ProfileKey   string
	Version      int
	SystemPrompt string
	Note         string
	Source       string
	ActorID      *int64
	CreatedAt    time.Time
}

// Validate checks the revision identity, body and source.
func (r PromptRevision) Validate() error {
	if strings.TrimSpace(r.ProfileKey) == "" {
		return platform.Invalid("profile_key", "must not be empty")
	}
	if r.Version <= 0 {
		return platform.Invalid("version", "must be a positive integer")
	}
	if strings.TrimSpace(r.SystemPrompt) == "" {
		return platform.Invalid("system_prompt", "must not be empty")
	}
	if err := ValidatePromptSource(r.Source); err != nil {
		return err
	}
	return nil
}

// PromptVersionInfo is the current revision metadata of one profile.
type PromptVersionInfo struct {
	Version   int
	CreatedAt time.Time
}

// PromptWrite is one checked prompt append request. ExpectedVersion is the
// optional optimistic lock, and NoOpOnSame skips the append when the submitted
// body equals the current agent_profile.system_prompt (PUT no-op semantics).
type PromptWrite struct {
	ProfileKey      string
	SystemPrompt    string
	Note            string
	Source          string
	ActorID         *int64
	ExpectedVersion *int
	NoOpOnSame      bool
}

// Validate checks the write identity, source and optimistic lock.
func (w PromptWrite) Validate() error {
	if strings.TrimSpace(w.ProfileKey) == "" {
		return platform.Invalid("key", "must not be empty")
	}
	if strings.TrimSpace(w.SystemPrompt) == "" {
		return platform.Invalid("system_prompt", "must not be empty")
	}
	if err := ValidatePromptSource(w.Source); err != nil {
		return err
	}
	if w.ExpectedVersion != nil && *w.ExpectedVersion <= 0 {
		return platform.Invalid("expected_version", "must be a positive integer")
	}
	return nil
}

// PromptWriteResult reports the current version after a prompt write and
// whether a new revision was appended.
type PromptWriteResult struct {
	Version int
	Changed bool
}

// ProfileUpdate describes one partial profile PATCH. SetModel distinguishes
// "field absent" (false) from "clear to default" (true with Model nil or empty).
type ProfileUpdate struct {
	SetModel     bool
	Model        *string
	Budgets      *ProfileBudgets
	AllowedTools *[]string
}

// Empty reports whether no writable field is present.
func (u ProfileUpdate) Empty() bool {
	return !u.SetModel && u.Budgets == nil && u.AllowedTools == nil
}

// ValidatePromptSource checks the frozen revision source enum.
func ValidatePromptSource(source string) error {
	switch source {
	case PromptSourceSeed, PromptSourceAdmin, PromptSourceReset:
		return nil
	default:
		return platform.Invalid("source", "must be one of seed, admin, reset")
	}
}

// ValidatePrompt validates a full profile prompt body: non-empty, bounded,
// keeps the [profile:<key>] marker and is a template restricted to the
// code-defined variable catalog (spec §8.4).
func ValidatePrompt(key, prompt string, catalog []PromptVariable) error {
	if strings.TrimSpace(prompt) == "" {
		return platform.Invalid("system_prompt", "must not be empty")
	}
	if utf8.RuneCountInString(prompt) > MaxPromptRunes {
		return platform.Invalid("system_prompt", "must be at most 32768 characters")
	}
	if !strings.Contains(prompt, "[profile:"+key+"]") {
		return promptError("missing_profile_marker", "must keep the [profile:"+key+"] marker")
	}
	return ValidatePromptTemplate(prompt, catalog)
}

// ValidatePromptTemplate checks the Go text/template syntax and requires every
// dynamic value to be a direct top-level {{.Variable}} of the catalog. No
// function calls, pipelines or nested field access are allowed.
func ValidatePromptTemplate(prompt string, catalog []PromptVariable) error {
	if strings.TrimSpace(prompt) == "" {
		return platform.Invalid("system_prompt", "must not be empty")
	}
	parsed, err := template.New("system_prompt").Option("missingkey=error").Parse(prompt)
	if err != nil {
		return promptError("invalid_template", "invalid template syntax: "+err.Error())
	}
	if parsed.Tree == nil || parsed.Tree.Root == nil {
		return promptError("invalid_template", "invalid template")
	}
	allowed := make(map[string]struct{}, len(catalog))
	for _, variable := range catalog {
		allowed[variable.Name] = struct{}{}
	}
	return validatePromptNodes(parsed.Tree.Root.Nodes, allowed)
}

func validatePromptNodes(nodes []parse.Node, allowed map[string]struct{}) error {
	for _, node := range nodes {
		switch typed := node.(type) {
		case *parse.TextNode:
			continue
		case *parse.ActionNode:
			if err := validatePromptPipe(typed.Pipe, allowed); err != nil {
				return err
			}
		case *parse.IfNode:
			if err := validatePromptPipe(typed.Pipe, allowed); err != nil {
				return err
			}
			if err := validatePromptBranch(typed.List, typed.ElseList, allowed); err != nil {
				return err
			}
		case *parse.RangeNode:
			if err := validatePromptPipe(typed.Pipe, allowed); err != nil {
				return err
			}
			if err := validatePromptBranch(typed.List, typed.ElseList, allowed); err != nil {
				return err
			}
		case *parse.WithNode:
			if err := validatePromptPipe(typed.Pipe, allowed); err != nil {
				return err
			}
			if err := validatePromptBranch(typed.List, typed.ElseList, allowed); err != nil {
				return err
			}
		default:
			return promptError("invalid_template", "template supports only text, variables and if/range/with blocks")
		}
	}
	return nil
}

func validatePromptBranch(list, elseList *parse.ListNode, allowed map[string]struct{}) error {
	if list != nil {
		if err := validatePromptNodes(list.Nodes, allowed); err != nil {
			return err
		}
	}
	if elseList != nil {
		if err := validatePromptNodes(elseList.Nodes, allowed); err != nil {
			return err
		}
	}
	return nil
}

func validatePromptPipe(pipe *parse.PipeNode, allowed map[string]struct{}) error {
	if pipe == nil || len(pipe.Decl) > 0 || len(pipe.Cmds) != 1 {
		return promptError("invalid_template", "template supports only direct {{.Variable}} substitutions")
	}
	command := pipe.Cmds[0]
	if command == nil || len(command.Args) != 1 {
		return promptError("invalid_template", "template supports only direct {{.Variable}} substitutions")
	}
	field, ok := command.Args[0].(*parse.FieldNode)
	if !ok {
		return promptError("invalid_template", "template supports only direct {{.Variable}} substitutions")
	}
	if len(field.Ident) != 1 {
		return promptError("unknown_variable", "unknown template variable ."+strings.Join(field.Ident, "."))
	}
	if _, ok := allowed[field.Ident[0]]; !ok {
		return promptError("unknown_variable", "unknown template variable ."+field.Ident[0])
	}
	return nil
}

func promptError(reason, message string) error {
	err := platform.Invalid("system_prompt", message)
	err.Details["reason"] = reason
	return err
}
